content.content:
PYTHONPATH=/home/user/thyrox/src:/home/user/thyrox/src:/home/user/thyrox/src
THYROX_ROOT=/home/user/thyrox
 echo "reach.sh: no se hallo $THYROX_SH_MARKER ascendiendo desde $from_dir" "ni desde $PWD. Declara THYROX_ROOT o invoca desde dentro del arbol." 1>&2;
 root_bun="$(thyrox_toolchain_provider_root 2> /dev/null)" || root_bun='$THYROX_ROOT';
BASH_FUNC_thyrox_toolchain_provider_root%%=() {  if [[ -n "${THYROX_ROOT:-}" ]]; then
 printf '%s' "$THYROX_ROOT";
 root="$(thyrox_toolchain_provider_root 2> /dev/null)" || root='$THYROX_ROOT';
done

